-- S1-08 audit_logs (0023): monthly partitions, managed by pg_partman 5 (schema `partman`, created by
-- initdb; app_owner's grants come from the role bootstrap, which must run with DATABASE_URL_ADMIN first).
-- Premake 4 = the current month plus the next 4; `infinite_time_partitions` keeps creating them even when
-- no rows arrive. No default partition: a row outside every partition fails loudly instead of landing
-- where it would later block partman from creating that month. Maintenance: `app_partition_maintenance()`
-- (generated by `pnpm db:rls`), run hourly by the worker job `compliance.maintainPartitions`.
-- Retention stays NULL (rows are kept; a guard test checks it). Partitions get no grants
-- (`inherit_privileges` off): reached only through the parent.
SELECT partman.create_parent(
  p_parent_table := 'public.audit_logs',
  p_control := 'occurred_at',
  p_interval := '1 month',
  p_premake := 4,
  p_default_table := false
);--> statement-breakpoint
UPDATE partman.part_config
   SET infinite_time_partitions = true, inherit_privileges = false, retention = NULL
 WHERE parent_table = 'public.audit_logs';--> statement-breakpoint
-- Append-only, also for the owner and superusers: no app role holds UPDATE, DELETE or TRUNCATE (grants,
-- `pnpm db:rls`); these triggers refuse them for everyone else too. Old months leave only by partition
-- retention (DROP of a whole partition), which is off. Security invoker, EXECUTE revoked (triggers fire
-- without it). The row trigger is cloned onto every partition; TRUNCATE is refused on the parent.
create or replace function audit_logs_immutable() returns trigger language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  raise exception 'audit_logs is append-only (%)', tg_op using errcode = '42501';
end $$;--> statement-breakpoint
revoke all on function audit_logs_immutable() from public;--> statement-breakpoint
drop trigger if exists audit_logs_immutable on audit_logs;--> statement-breakpoint
create trigger audit_logs_immutable before update or delete on audit_logs
  for each row execute function audit_logs_immutable();--> statement-breakpoint
drop trigger if exists audit_logs_no_truncate on audit_logs;--> statement-breakpoint
create trigger audit_logs_no_truncate before truncate on audit_logs
  for each statement execute function audit_logs_immutable();
